var mx10004LC9600AddedOIDNames = []string{}

var mx10004LC9600RemovedOIDNames = []string{}

func restoreMx10004LC9600(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	reverseProfileEdits(t, cur, juniperMx10004Profile, "juniper_mx10004 LC9600", mx10004LC9600Edits)
}

func mx10004LC9600OIDNamesBefore(t *testing.T, names []string) []string {
	t.Helper()
	return reverseOIDNameEdits(t, names, "juniper_mx10004 LC9600", mx10004LC9600AddedOIDNames, mx10004LC9600RemovedOIDNames)
}

func TestMx10004LC9600ReproducesTheParentCorpus(t *testing.T) {
	if got := corpusTagDigestAt(t, corpusValuesAt(t, mx10004LC9600ParentRevision), mx10004LC9600ParentRevision); got != shippedTagDigestBeforeMx10004LC9600 {
		t.Errorf("reversing the LC9600 change gives digest %s, want %s: another shipped row changed without being recorded",
			got, shippedTagDigestBeforeMx10004LC9600)
	}
}

func TestMx10004LC9600RePinIsOnlyTheEdit(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), mx10004LC9600ParentRevision)
	if got := corpusOIDNameDigest(restored); got != shippedOIDEncodingDigestBeforeMx10004LC9600 {
		t.Errorf("reversing the LC9600 OID names gives digest %s, want %s", got, shippedOIDEncodingDigestBeforeMx10004LC9600)
	}
}
